// energy/degradation sketch for: Thermal-to-Electrical System Optimizer
let c = 1.0; const samples = [];
for (let i = 0; i < 609; i++) { c *= 0.99971; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 609, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

